import {hostNextStep} from './host-guide.js';
import {openAiAssistant} from './ai-assistant.js';
import {id,clone,newPlay,current,select,score,undo,closeClue,view,validate,representative,answerer} from './engine.js';
import {library,themes,makeGame} from './catalog.js';
import {openStore,read,write,api} from './store.js';
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,act,cls='',extra='')=>`<button class="${cls}" data-action="${act}" ${extra}>${text}</button>`;
let games=[],game,play=null,room=null,tab='home',editRound=0,editing=null,editUndo=[],remote=null,submissions={},polling=false,saving=false,saveTimer,dirty=false,queued=false,resetBuzz=false,clearSubmissions=false,saveState='Saved on this device',catalog=clone(library),search='',selectedSlot=0,playerRoom=null,playerData=null,localPublic=null,channel=new BroadcastChannel('shane-family-public-v1'),musicTimer=null,audioContext=null,showSound=false,setupTeams=[],connecting=false,buzzPending=false,clockOffset=0,lastPollAt=0,buzzShown={at:0,shown:0},hostRetired=false,recoverCode=null;
const serverNow=()=>Date.now()+clockOffset;
const params=new URLSearchParams(location.search),mode=params.get('mode')||'host',initialCode=params.get('room')||'';
const avatar=t=>t.photo?`<img class="avatar" alt="" src="${esc(t.photo)}">`:`<span class="avatar">${esc(t.name?.slice(0,1)||'?')}</span>`;
const field=(label,name,value,type='text')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}"></label>`;
const textField=(label,name,value)=>`<label class="field">${label}<textarea name="${name}">${esc(value)}</textarea><button type="button" class="tiny ghost" data-dictate="${name}">◉ Dictate</button></label>`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function modal(html){$('#modal').innerHTML=`<div class="modal-head"><span></span>${btn('×','dismiss','ghost','aria-label="Close dialog"')}</div>`+html;$('#modal').showModal();}
function dismiss(){$('#modal').close();editing=null;}
function settings(){return game?.settings||{master:.6,effects:.6,music:0};}
function tone(kind='select'){const s=settings();if(s.muted||(mode==='stage'&&!showSound))return;const custom=s.sounds?.[kind];if(custom){const a=new Audio(custom.data);a.volume=s.master*s.effects;a.play().catch(()=>{});return;}try{audioContext||=new AudioContext();audioContext.resume();const notes={select:[440,660],buzz:[220,440,880],correct:[523,659,784],wrong:[220,160],double:[330,440,660,880],reveal:[392,523],timer:[660],win:[523,659,784,1046]};(notes[kind]||notes.select).forEach((f,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+i*.12;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(s.master*s.effects*.13,t);g.gain.exponentialRampToValueAtTime(.001,t+.28);o.connect(g).connect(audioContext.destination);o.start(t);o.stop(t+.3);});}catch{}}
function setMusic(){clearInterval(musicTimer);musicTimer=null;if(settings().music>0&&!settings().muted){let n=0;musicTimer=setInterval(()=>{try{audioContext||=new AudioContext();const o=audioContext.createOscillator(),g=audioContext.createGain();o.frequency.value=[130.81,164.81,196,164.81][n++%4];g.gain.value=settings().master*settings().music*.035;o.connect(g).connect(audioContext.destination);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.7);o.start();o.stop(audioContext.currentTime+.8);}catch{}},850);}}
function theme(){document.body.className=(game?.theme||remote?.theme||'Classic').toLowerCase().replace('’','').replaceAll(' ','-');if(settings().motion===false)document.body.classList.add('reduced');}
async function save(){if(mode!=='host')return;try{await write('studio',{games,selected:game?.id,play,room,catalog});saveState=window.GAME_NIGHT_CLOUD?'Saved privately to your account':'Saved on this device';$('.status')&&($('.status').textContent=saveState);}catch(e){saveState=e.message||'Save failed — export a backup';toast(saveState);}}
function changed(network=true){game.updated=Date.now();clearTimeout(saveTimer);saveTimer=setTimeout(save,180);if(play){localPublic=view(game,play);channel.postMessage({type:'stage',view:localPublic});write('public-stage',localPublic).catch(()=>{});}if(network&&room){dirty=true;sync();}}
function head(){return `<header class="top"><button class="brand brand-text-only brand-home" data-action="home"><span><strong>← Main menu</strong></span></button><nav>${[['games','My games'],['builder','Game builder'],['settings','Sound & settings']].map(([a,t])=>btn(t,a,tab===a?'active':'')).join('')}</nav><span class="status">${esc(saveState)}</span>${window.GAME_NIGHT_CLOUD?`${window.GAME_USER?.owner?btn('Game Masters','manage-hosts','ghost'):''}${btn('Log out','logout','ghost')}`:''}${btn('Join a room ↗','join','ghost join-top')}</header>`;}
function render(){setTimeout(markSlotDots);setTimeout(fitNames);theme();if(mode==='stage'){renderStagePage();return;}if(mode==='player'){renderPlayer();return;}$('#app').innerHTML=`<div class="shell ${tab==='home'?'menu-shell':tab==='host'?'host-shell':''}">${tab==='home'?'':head()}${tab==='home'?home():tab==='games'?gamesPage():tab==='builder'?builder():tab==='settings'?settingsPage():host()}<footer class="footer ${tab==='home'?'hidden':''}"><span>MADE FOR YOUR PEOPLE. BUILT FOR THE BIG SCREEN.</span><span>${window.GAME_NIGHT_CLOUD?'Games saved privately to your account':'Game edits saved on this device'}</span></footer></div>`;}
// Landing-page tour: spotlights each button in turn. Steps whose button isn't on screen are skipped.
const tourSteps=[
 {title:'Welcome to Ultimate Game Night!',text:'Here’s a 30-second tour of the main menu. Tap Next to go through each button.'},
 {sel:'.ugn-live',title:'Jump back in',text:'Your game is still going. This takes you straight back to it, with scores, players and the board exactly as you left them.'},
 {sel:'.ugn-big.ugn-host',title:'▶ Host a Game',text:'Start game night. Name your teams and your Game Master console opens. Press “Open TV board” there to put the board on your TV; everyone joins by scanning the QR code.'},
 {sel:'.ugn-big.ugn-join',title:'ϟ Join a Room',text:'For players’ phones. Type the 6-letter room code from the TV and your name, pick a team, and your phone becomes your buzzer.'},
 {sel:'.ugn-chip[data-action="games"]',title:'▦ My Games',text:'All your saved boards. Host, edit or back up any of them.'},
 {sel:'.ugn-chip[data-action="create"]',title:'＋ New Game',text:'Make a brand-new board from a ready-made starter, then make it yours in the Game Builder.'},
 {sel:'.ugn-chip[data-action="builder"]',title:'✎ Game Builder',text:'Edit categories, questions, answers, point values and Daily Doubles, and add pictures or music clues.'},
 {sel:'.ugn-chip[data-action="import"]',title:'↑ Import',text:'Load a game file (.json) that you or a friend exported. Great for sharing boards.'},
 {sel:'.ugn-home-utilities [data-action="settings"]',title:'⚙ Settings',text:'Pick a theme, set the answer timer, and adjust sounds and music.'},
 {sel:'.ugn-home-utilities [data-action="manage-hosts"]',title:'Game Masters',text:'Owner only: create and manage the logins for other Game Masters.'},
 {sel:'.ugn-home-utilities [data-action="fullscreen"]',title:'⛶ Fullscreen',text:'Fill the whole screen. Perfect on the TV.'},
 {sel:'.tour-chip',title:'That’s it!',text:'Replay this tour anytime with “How it works”. Now go host a game night!'}];
let tourStep=-1;
const tourList=()=>tourSteps.filter(s=>!s.sel||document.querySelector(s.sel));
function drawTour(){$('#tour')?.remove();if(tourStep<0)return;const list=tourList(),s=list[tourStep];if(!s){tourStep=-1;return;}const el=s.sel&&document.querySelector(s.sel),r=el?.getBoundingClientRect(),last=tourStep===list.length-1,wrap=document.createElement('div');wrap.id='tour';wrap.className='tour';wrap.innerHTML=`${r?`<div class="tour-spot" style="left:${r.left-8}px;top:${r.top-8}px;width:${r.width+16}px;height:${r.height+16}px"></div>`:'<div class="tour-dim"></div>'}<div class="tour-card" role="dialog" aria-modal="true" aria-label="${esc(s.title)}"><div class="tour-dots">${list.map((x,i)=>`<span class="${i===tourStep?'on':''}"></span>`).join('')}</div><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p><div class="tour-actions">${tourStep?btn('← Back','tour-back','ghost'):btn('Skip','tour-end','ghost')}${btn(last?'Let’s play! 🎉':'Next →','tour-next','primary')}</div></div>`;document.body.append(wrap);const card=wrap.querySelector('.tour-card'),h=card.offsetHeight,w=card.offsetWidth,pad=12;let top=r?(r.bottom+16+h<innerHeight?r.bottom+16:Math.max(pad,r.top-16-h)):(innerHeight-h)/2,left=r?r.left+r.width/2-w/2:(innerWidth-w)/2;card.style.top=Math.round(top)+'px';card.style.left=Math.round(Math.min(innerWidth-w-pad,Math.max(pad,left)))+'px';wrap.querySelector('.tour-actions .primary').focus();}
function startTour(){tourStep=0;try{localStorage.setItem('ugn-tour-seen','1');}catch{}drawTour();}
addEventListener('resize',()=>{if(tourStep>=0)drawTour();});
addEventListener('keydown',e=>{if(tourStep<0)return;if(e.key==='Escape'){tourStep=-1;drawTour();}else if(e.key==='ArrowRight'){action('tour-next');}else if(e.key==='ArrowLeft'&&tourStep>0){action('tour-back');}});
function home(){return `<main class="game-menu ugn-home" aria-label="Ultimate Game Nite main menu"><picture class="menu-art"><source media="(max-width:700px)" srcset="assets/menu-neon-mobile.jpg"><img src="assets/menu-neon.jpg" alt="Ultimate Game Night" fetchpriority="high"></picture><section class="ugn-hero-copy"><div class="ugn-main-actions">${room?btn('↩ Rejoin Room '+esc(room.code),'rejoin-room','ugn-big ugn-live'):play?btn('↻ Resume Game','resume','ugn-big ugn-live'):''}${btn('▶ Host a Game','setup','ugn-big ugn-host')}${btn('ϟ Join a Room','join','ugn-big ugn-join')}</div><div class="ugn-more-actions">${btn('▦ My Games','games','ugn-chip')}${btn('＋ New Game','create','ugn-chip')}${btn('✎ Game Builder','builder','ugn-chip')}${btn('↑ Import','import','ugn-chip')}</div>${room?btn('↪ Leave Room','disconnect','ugn-leave-room'):''}</section><div class="ugn-home-utilities">${btn('? How it works','tour-start','menu-small tour-chip')}${btn('⚙ Settings','settings','menu-small')}${window.GAME_NIGHT_CLOUD?`${window.GAME_USER?.owner?btn('Game Masters','manage-hosts','menu-small'):''}${btn('Log out','logout','menu-small')}`:''}${btn('⛶ Fullscreen','fullscreen','menu-small')}</div></main>`;}
function gamesPage(){return `<section class="divider games-library"><div class="games-hero"><picture class="games-hero-art"><source media="(max-width:700px)" srcset="assets/menu-neon-mobile.jpg"><img src="assets/menu-neon.jpg" alt=""></picture><div class="games-hero-content"><div class="ugn-main-actions games-actions">${room?btn('↩ Rejoin Room '+esc(room.code),'rejoin-room','ugn-big ugn-live'):play?btn('↻ Resume Game','resume','ugn-big ugn-live'):''}${btn('＋ New Game','create','ugn-big ugn-host')}${btn('↑ Import Game','import','ugn-big ugn-join')}</div>${room?btn('↪ Leave Room','disconnect','ugn-leave-room'):''}</div></div><div class="game-library-head"><div><div class="eyebrow">SAVED GAMES</div><h2>Your lineup</h2></div></div><div class="grid game-library-grid">${games.map(g=>`<article class="card game-card"><span class="badge">${esc(g.theme)} edition</span><h2>${esc(g.name)}</h2><small>2 rounds · 60 clues · Final showdown</small><div class="actions">${btn('▶ Host','setup','game-host',`data-id="${g.id}"`)}${btn('✎ Edit','edit-game','game-edit',`data-id="${g.id}"`)}${btn('•••','game-menu','tiny ghost',`data-id="${g.id}"`)}</div></article>`).join('')}<button class="new-card compact-new-card" data-action="create"><b>＋</b><strong>Create New Game</strong><small>Start with a full board. Make it yours.</small></button></div></section>`;}

// Builder categories sit in a sideways carousel; the chips under it light up for the cards in view.
function markSlotDots(){const row=$('#slots');if(!row)return;const box=row.getBoundingClientRect();[...row.children].forEach((card,i)=>{const r=card.getBoundingClientRect(),seen=r.left>=box.left-4&&r.right<=box.right+4;document.querySelector(`.slot-dot[data-index="${i}"]`)?.classList.toggle('on',seen);});const prev=$('.car-prev'),next=$('.car-next');if(prev)prev.disabled=row.scrollLeft<=2;if(next)next.disabled=row.scrollLeft+row.clientWidth>=row.scrollWidth-2;}
addEventListener('scroll',e=>{if(e.target?.id==='slots')markSlotDots();},true);addEventListener('resize',markSlotDots);
function builder(){return `<div class="toolbar"><div><div class="eyebrow">The creative department</div><h2>${esc(game.name)}</h2></div><div class="actions">${window.GAME_NIGHT_CLOUD?btn('✦ AI assistant','ai-assistant','purple tiny'):''}${btn('Game details','details','tiny')}${btn('Undo edit','undo-edit','tiny',editUndo.length?'':'disabled')}${btn('Export backup','export','tiny')}${btn('▶ Play','setup','primary tiny')}</div></div><div class="builder"><aside class="card library"><h3>Category library</h3><input id="search" placeholder="Find a category…" value="${esc(search)}" aria-label="Search categories">${btn('＋ New category','new-category','tiny')}<div id="library-list">${libraryList()}</div></aside><section><div class="tabs">${[0,1].map(r=>btn(`Round ${r+1}`,`round-${r}`,editRound===r?'active':'')).join('')}${btn('Final showdown','edit-final',editRound===2?'active':'')}</div><p class="help">One Daily Double per round. Select any clue to write, dictate, or attach media. Gold stars mark the host-only Daily Double.</p><div class="slot-carousel">${btn('‹','slots-prev','car-arrow car-prev','aria-label="Previous categories"')}<div class="slots" id="slots">${game.rounds[editRound>1?0:editRound].map((c,i)=>`<article class="slot" data-slot="${i}" style="${selectedSlot===i?'border-color:var(--accent)':''}"><div class="slot-title"><button class="tiny ghost" data-action="select-slot" data-index="${i}" aria-label="Select slot ${i+1}">${i+1}</button><h3>${esc(c.name)}</h3>${btn('•••','category-menu','tiny ghost',`data-index="${i}"`)}</div>${c.clues.map(q=>`<button class="clue-row" data-action="edit-clue" data-id="${q.id}"><b>${q.value}${q.dailyDouble?'★':''}</b><span>${esc(q.question)||'Write a clue…'}${q.media?' ▣':''}</span></button>`).join('')}</article>`).join('')}</div>${btn('›','slots-next','car-arrow car-next','aria-label="Next categories"')}</div><div class="slot-dots" role="tablist" aria-label="Categories">${game.rounds[editRound>1?0:editRound].map((c,i)=>btn(`${i+1} · ${esc(c.name)}`,'slots-go','slot-dot',`data-index="${i}"`)).join('')}</div></section></div>`;}
// Library items are draggable divs (Firefox will not drag buttons); tapping one opens a slot picker instead.
function libraryList(){return catalog.filter(c=>c.name.toLowerCase().includes(search.toLowerCase())).map(c=>`<div class="lib-item" role="button" tabindex="0" draggable="true" data-drag="${c.id}" data-action="add-category" data-id="${c.id}" title="Drag onto a category, or tap to choose a slot"><span class="lib-grip" aria-hidden="true">⋮⋮</span>${esc(c.name)}<span class="lib-plus">＋</span></div>`).join('');}
function mediaHtml(m){if(!m)return '';if(m.type==='youtube'){if(mode!=='host')return '<div class="music-mystery"><span>♫</span><strong>NAME THAT TRACK</strong><p>Listen to the Game Master’s audio.</p></div>';return `<iframe class="youtube-clue" src="https://www.youtube-nocookie.com/embed/${esc(m.videoId)}?start=${Math.floor(m.start||0)}" title="YouTube music clue" allow="autoplay; encrypted-media" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;}if(!m.data||(!m.data.startsWith('data:')&&!safeMediaUrl(m.data)))return '';if(m.type.startsWith('image/'))return `<img class="media" src="${esc(m.data)}" alt="Clue image">`;if(m.type.startsWith('video/'))return `<video class="media" src="${esc(m.data)}" controls playsinline ${settings().autoplay?'autoplay':''}></video>`;if(m.type.startsWith('audio/'))return `<div class="music-mystery"><span>♫</span><strong>NAME THAT TRACK</strong><audio class="media" src="${esc(m.data)}" controls ${settings().autoplay?'autoplay':''}></audio></div>`;return '';}
function safeMediaUrl(value){try{const url=new URL(value);return url.protocol==='https:'&&!url.username&&!url.password;}catch{return false;}}
function linkedMedia(value){const url=new URL(value);if(!safeMediaUrl(value))throw Error('Use an HTTPS media link');const host=url.hostname.replace(/^www\./,'');let videoId;if(host==='youtu.be')videoId=url.pathname.slice(1);else if(['youtube.com','m.youtube.com','music.youtube.com'].includes(host))videoId=url.searchParams.get('v')||url.pathname.split('/').filter(Boolean).at(-1);if(videoId&&/^[a-zA-Z0-9_-]{11}$/.test(videoId)){const raw=url.searchParams.get('t')||url.searchParams.get('start')||'0';const match=raw.match(/^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/);const start=match?Number(match[1]||0)*3600+Number(match[2]||0)*60+Number(match[3]||0):parseInt(raw)||0;return {type:'youtube',videoId,start,name:'Music clue'};}if(!/\.(mp3|wav|ogg|m4a)(?:$)/i.test(url.pathname))throw Error('Paste a direct MP3, WAV, OGG or M4A URL, or a YouTube video link. Music-site pages cannot play as audio files.');return {type:'audio/mpeg',data:url.href,name:'Music clue'};}
async function clueMedia(file){if(!editing)throw Error('Open a clue first');if(file?.type.startsWith('image/')){const draft=editing,fields=Object.fromEntries(new FormData($('#clue-form')));await crop(file,async photo=>{const media=window.GAME_NIGHT_CLOUD?await uploadClueBlob(await(await fetch(photo)).blob()):{type:'image/jpeg',data:photo,name:'Clue image'};editClue(draft.q.id,draft.final);for(const [key,value]of Object.entries(fields)){const input=$('#clue-form').elements.namedItem(key);if(input){if(input.type==='checkbox')input.checked=true;else input.value=value;}}editing.media=media;$('#media-preview').innerHTML=mediaHtml(media);},true);}else{editing.media=window.GAME_NIGHT_CLOUD?await uploadClueBlob(file):await fileData(file);$('#media-preview').innerHTML=mediaHtml(editing.media);}}
async function uploadClueBlob(blob){if(blob.size>3000000)throw Error('Use a clip smaller than 3 MB');const response=await fetch('/api/game-night/media',{method:'POST',headers:{'Content-Type':blob.type},body:blob});const data=await response.json();if(!response.ok)throw Error(data.error);return data;}
async function manageHosts(){const response=await fetch('/api/game-night/hosts'),data=await response.json();if(!response.ok)throw Error(data.error);modal(`<h2>Game Masters</h2><p class="help">Only your master admin can create, reset or disable host accounts. Each host has private saved games.</p><div class="host-account-list">${data.hosts.map(h=>`<div class="list-row"><strong>${esc(h.display_name||h.username)}<small> · ${esc(h.username)}</small></strong><div class="actions">${btn(h.is_enabled?'Disable':'Enable','toggle-host','tiny',`data-id="${esc(h.username)}" data-enabled="${h.is_enabled}"`)}${btn('Reset password','reset-host-password','tiny',`data-id="${esc(h.username)}"`)}</div></div>`).join('')||'<p>No Game Masters added yet.</p>'}</div><form id="host-account-form">${field('Username','username','')}${field('Display name','displayName','')}${field('Password · at least 12 characters','password','','password')}<button class="primary">Add Game Master</button></form>`);}
async function hostAccount(data){const response=await fetch('/api/game-night/hosts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error);await manageHosts();}

function stage(v,clickable=false){if(!v)return '<div class="empty">Open a game in the host console to bring this stage to life.</div>';const phase=v.phase;let body='';if(phase==='board')body=`<div class="board">${v.board.map(c=>`<div class="column"><div class="category">${esc(c.name)}</div>${c.clues.map(q=>`<button class="tile ${v.used.includes(q.id)?'used':''}" ${clickable&&!v.used.includes(q.id)?`data-action="pick" data-id="${q.id}"`:'disabled'} aria-label="${esc(c.name)} for ${q.value}">${q.value}</button>`).join('')}</div>`).join('')}</div>`;else if(phase==='double')body='<div class="stage-question"><div class="eyebrow">A chance to change everything</div><div class="big-label">DAILY<br>DOUBLE</div><p class="muted">Choose your wager.</p></div>';else if(phase==='final-category')body=`<div class="stage-question"><div class="eyebrow">Final showdown · Place your wagers</div><div class="big-label" style="font-size:50px;margin:30px 0">${esc(v.finalCategory)}</div><p class="muted">One last question. Make it count.</p></div>`;else if(phase==='standings'){const sorted=[...v.teams].sort((a,b)=>b.score-a.score),best=sorted[0]?.score;body=`<div class="stage-question"><div class="spark">✦</div><div class="eyebrow">Tonight belongs to</div><div class="winners">${sorted.filter(t=>t.score===best).map(t=>esc(t.name)).join(' & ')}</div><p>${best??0} points · ${sorted.filter(t=>t.score===best).length>1?'Joint champions':'Champion'}</p>${sorted.map((t,i)=>`<div class="list-row" style="width:100%;max-width:500px"><span>${i+1}. ${esc(t.name)}</span><b>${t.score}</b></div>`).join('')}</div>`;}else body=`<div class="stage-question"><div class="eyebrow">${phase.startsWith('final')?'Final showdown':`Round ${v.round+1}`}</div>${mediaHtml(v.clue?.media)}<h2>${esc(v.clue?.question)}</h2>${v.clue?.answer?`<div class="answer">${esc(v.clue.answer)}</div>`:''}</div>`;return `<div class="stage"><div class="stage-head"><h3>ϟ &nbsp; ${esc(v.title)}</h3><span class="eyebrow">${room?.code||initialCode?`ROOM ${esc(room?.code||initialCode)}`:`ROUND ${v.round+1}`}</span><span class="timer" data-deadline="${v.deadline||''}"></span></div>${v.phase==='board'?`<div class="stage-instruction"><span>UP NEXT</span><strong data-fit="16">${esc(v.teams.find(t=>t.id===v.active)?.name||'Game Master')} ${v.teamMode&&v.representatives?.[v.active]?.name?'· '+esc(v.representatives[v.active].name):''}</strong><p>CHOOSE A CATEGORY & POINT VALUE</p></div>`:v.phase==='clue'&&!v.revealed?`<div class="stage-instruction">${clueBanner(v)}</div>${v.roast&&!(v.winner&&v.judged?.includes(v.winner))?`<div class="stage-roast">${esc(v.roast)}</div>`:''}`:''}${body}<div class="scoreboard">${v.teams.map(t=>`<div class="team ${t.id===(v.winner||v.active)?'active':''}" style="--c:${esc(teamColor(v,t))}">${avatar(t)}<div><small data-fit="11">${esc(t.name)}</small><b>${t.score}</b>${v.teamMode?`<span class="score-answerer">${esc((v.phase==='board'?v.representatives:v.answerers||v.representatives)?.[t.id]?.name||'No player assigned')}</span>`:''}</div></div>`).join('')}</div></div>`;}
function clueBanner(v){const name=id=>esc(v.teams.find(t=>t.id===id)?.name||''),person=v.players?.find(p=>p.id===v.winnerPlayer)?.name||v.answerers?.[v.winner]?.name||'';if(v.winner&&v.judged?.includes(v.winner))return `<strong>✓ ${name(v.winner)} GOT IT!</strong><p>${name(v.winner)} PICKS NEXT</p>`;if(v.buzzOpen)return `<strong class="countdown" data-countdown="${v.buzzStartsAt||0}">${v.buzzStartsAt&&serverNow()<v.buzzStartsAt?Math.min(3,Math.ceil((v.buzzStartsAt-serverNow())/1000)):'BUZZ!'}</strong><p>STEAL! FASTEST BUZZ ANSWERS</p>`;if(v.winner)return `<span>${v.judged?.length?'STEAL':'NO BUZZ NEEDED'}</span><strong>${name(v.winner)}${v.teamMode&&person?' · '+esc(person):''}</strong><p>${v.judged?.length?'ANSWER FOR THE STEAL':'YOU’RE UP · ANSWER NOW'}</p>`;if(v.judged?.length&&v.judged.length<v.teams.length)return `<strong>STEAL CHANCE</strong><p>GAME MASTER WILL OPEN BUZZERS</p>`;if(v.judged?.length)return `<strong>NOBODY GOT IT</strong><p>${name(v.pickTeam||v.active)} PICKS NEXT</p>`;return `<strong>GET READY</strong><p>THE GAME MASTER IS READING THE CLUE</p>`;}
function hostGuideCard(){const step=hostNextStep(play,room,current(game,play));return `<section class="card host-guide" aria-label="Game Master next step"><div class="eyebrow">YOUR NEXT STEP · ${room?'ROOM '+esc(room.code):'LOCAL PLAY — PHONES NOT CONNECTED'}</div><h3>${esc(step.title)}</h3><p>${esc(step.text)}</p><div class="actions">${step.action?btn(esc(step.button),step.action,'primary'):''}${btn('Step-by-step walkthrough','host-guide','purple tiny')}</div></section>`;}
function showHostGuide(index=0){const steps=[['Create your teams','Use Players & teams (under More) to name the teams.','teams','Players & teams'],['Open the TV board','Click Open TV board. It opens the board in a new window and creates the room. Drag that window to your TV and press Fullscreen. Your teams and scores carry over.','tv','Open TV board'],['Players join','Players scan the QR on the TV, enter their names, and choose a team. Keep the room code the same on every screen.',null,null],['Check players, then start','Use Players & teams to check everyone joined and chose a team. Close that panel, then click Start game. The displayed representative rotates each clue.','teams','Check players & teams'],['Pick and read a clue','The teammate on turn picks a category and value on their phone, or you tap it on your console. Read the question aloud. That same player answers first — no buzz needed.',null,null],['Judge, then steal','Click Correct or Wrong. Wrong loses full points. With 3+ teams, click Open buzzers: the TV counts 3-2-1 and the fastest buzz steals. A wrong steal loses half; the last team left answers automatically and loses nothing.',null,null],['Who picks next','Correct keeps or takes control. If nobody gets it, the team that picked keeps control. The player on turn rotates to the next teammate every clue.',null,null],['Return to the board','Click Return to board for the next clue and rotating players. Use Next round after round one, then Final showdown: collect wagers, lock them, read the final clue, reveal, judge each team, and show standings.',null,null]];const step=steps[Math.max(0,Math.min(7,index))];modal(`<div class="eyebrow">GAME MASTER WALKTHROUGH · ${index+1} OF 8</div><h2>${step[0]}</h2><p>${step[1]}</p>${step[2]?btn(step[3],step[2],'primary'):''}<div class="actions" style="margin-top:20px">${index?btn('← Back','guide-back','ghost',`data-index="${index-1}"`):''}${index<7?btn('Next →','guide-next','purple',`data-index="${index+1}"`):btn('Ready to host','dismiss','primary')}</div>`);}
function host(){if(!play)return home();const c=current(game,play),v=view(game,play);return `<div class="host-layout gm-layout" aria-label="Game Master console"><section class="host-board" aria-label="Game board">${stage(v,true)}</section><aside class="host-panel gm-panel" aria-label="Game Master control panel"><div class="host-panel-top"><h2>Game Master</h2><span>${room?'ROOM '+esc(room.code):'LOCAL PLAY'}</span></div><div class="gm-primary">${btn('📺 Open TV board','tv',room?'tiny':'primary')}${room&&!play.started?btn('▶ Start game','start-online-game','primary'):''}</div>${gmCard(c)}<details class="host-more-tools gm-more"><summary>More</summary><div class="actions">${btn('Players & teams','teams','tiny')}${room?btn('Room links & QR','connect','tiny'):''}${room&&play.started?btn('Show joining lobby','show-lobby','tiny'):''}${btn('Undo score','undo-score','tiny',play.history.length?'':'disabled')}${btn('Adjust score','adjust','tiny')}${btn('Next round →','next-round','tiny',play.phase!=='board'?'disabled':'')}${btn('Final showdown','final','tiny')}${btn('Display setup','display-help','tiny ghost')}${btn('Walkthrough','host-guide','tiny ghost')}</div>${hostRoster()}</details><div class="host-network-status"><p class="help" id="connection">${room?'Connected · Room '+esc(room.code):'Local game · Open TV board to bring phones in'}</p></div></aside></div>`;}
const teamName=id=>esc(play.teams.find(t=>t.id===id)?.name||'');
const gmStep=(label,act,lit,cls='',disabled=false)=>btn(label,act,`${lit?'primary gm-next':'ghost'} ${cls}`,disabled?'disabled':'');
function gmCard(c){
 if(play.phase==='board'){const pick=representative(play,play.active),ans=answerer(play,play.active);return `<section class="gm-card"><div class="eyebrow">UP NEXT</div><h3>${teamName(play.active)||'Choose a team'}</h3><p>${pick&&play.teamMode?`<b>${esc(pick.name)}</b> picks${ans&&ans.id!==pick.id?` · <b>${esc(ans.name)}</b> answers`:''}`:'Tap a value on the board to open a clue.'}</p>${room&&!play.started?'<p class="help">Players join from the QR on the TV. Press Start game when everyone is on a team.</p>':''}</section>`;}
 if(play.phase==='standings')return `<section class="gm-card"><div class="eyebrow">GAME OVER</div><h3>Celebrate your winners.</h3><p class="help">Final scores are on the TV.</p></section>`;
 if(play.phase==='double'){const t=play.teams.find(t=>t.id===play.active);return `<section class="gm-card"><div class="eyebrow">DAILY DOUBLE · ${teamName(play.active)}</div><label class="field">Wager (max ${Math.max(t?.score||0,500*(play.round+1))})<input id="dd-wager" type="number" min="0" value="${play.wager}"></label>${gmStep('Lock wager & show clue','lock-double',true)}</section>`;}
 if(play.phase==='final-category')return `<section class="gm-card"><div class="eyebrow">FINAL SHOWDOWN · WAGERS</div>${play.teams.map(t=>`<label class="field">${esc(t.name)} · max ${Math.max(t.score,0)}<input data-wager="${t.id}" type="number" min="0" max="${Math.max(t.score,0)}" value="${esc(play.wagers[t.id]??submissions[answerer(play,t.id)?.id]?.wager??0)}"></label>`).join('')}${gmStep('Lock wagers & start final','lock-final',true)}</section>`;
 if(!c)return '';
 const cat=play.phase.startsWith('final')?{name:game.finalCategory}:game.rounds[play.round].find(x=>x.clues.some(q=>q.id===play.selected)),final=play.phase.startsWith('final');
 const head=`<div class="eyebrow">${esc(cat?.name||'Clue')}${final?'':' · '+(c.dailyDouble?play.wager:c.value)}</div><p class="gm-question">${esc(c.question)}</p><div class="gm-answer"><small>ANSWER · ONLY YOU SEE THIS</small><strong>${esc(c.answer)}</strong>${c.accepted?`<small>Also accept: ${esc(c.accepted)}</small>`:''}${c.note?`<p class="help">${esc(c.note)}</p>`:''}${/^https?:\/\//.test(c.source||'')?`<a href="${esc(c.source)}" target="_blank" rel="noopener" class="help">Check source ↗</a>`:''}</div>${cat?.hostNarration?`<details class="gm-narration"><summary>Host narration</summary><p>${esc(cat.hostNarration)}</p>${btn('Read narration','read-narration','tiny')}</details>`:''}`;
 if(final)return `<section class="gm-card">${head}<div class="gm-steps">${gmStep('Reveal answer','reveal',!play.revealed,'',play.revealed)}${play.teams.map(t=>`<div class="gm-judge"><span>${esc(t.name)}${submissions[answerer(play,t.id)?.id]?.answer?` · “${esc(submissions[answerer(play,t.id).id].answer)}”`:''}</span>${btn('✓','correct','primary tiny',`data-team="${t.id}" ${play.judged.includes(t.id)?'disabled':''}`)}${btn('✕','wrong','danger tiny',`data-team="${t.id}" ${play.judged.includes(t.id)?'disabled':''}`)}</div>`).join('')}${gmStep('Show standings','standings',play.judged.length>=play.teams.length)}</div></section>`;
 const remaining=play.teams.filter(t=>!play.judged.includes(t.id)),answering=c.dailyDouble&&!play.resolved?play.active:play.winner&&!play.judged.includes(play.winner)?play.winner:null,got=play.resolved&&play.judged.includes(play.winner)?play.winner:null;
 const who=answering?(play.players||[]).find(p=>p.id===play.winnerPlayer)?.name||answerer(play,answering)?.name:'';
 const next=play.resolved?'close':answering?'judge':play.buzzOpen?'wait':remaining.length?'buzz':'close';
 const status=got?`✓ ${teamName(got)} got it · they pick next`:play.resolved?`Nobody got it · ${teamName(play.pickTeam||play.active)} picks next`:answering?`${play.judged.length?'STEAL · ':''}${teamName(answering)}${who&&play.teamMode?' · '+esc(who):''} is answering`:play.buzzOpen?'Buzzers open · waiting for the fastest buzz…':`Steal! ${remaining.length} teams can buzz`;
 const roast=!play.resolved&&play.roast!=null?`<p class="gm-roast">${esc(view(game,play).roast)}</p>`:'';
 return `<section class="gm-card">${head}<div class="gm-status gm-${next}">${status}</div>${roast}<div class="gm-steps">${c.dailyDouble?'':gmStep('▶ Open buzzers','open-buzz',next==='buzz','',play.resolved||play.revealed||!remaining.length||play.buzzOpen)}<div class="gm-judge">${gmStep('✓ Correct','correct',next==='judge','',!answering||play.resolved)}${gmStep('✕ Wrong','wrong',next==='judge','danger',!answering||play.resolved)}</div>${gmStep('Reveal answer','reveal',false,'',play.revealed)}${gmStep('Back to board →','close-clue',next==='close')}</div>${!play.resolved&&!c.dailyDouble?`<div class="gm-who"><small>Physical buzzer? Tap who answers:</small><div class="actions">${remaining.map(t=>btn(esc(t.name),'set-answering',`tiny ${t.id===answering?'purple':'ghost'}`,`data-team="${t.id}"`)).join('')}</div></div>`:''}${Object.keys(submissions).length?`<h3 class="gm-sub">Phone answers</h3>${(play.teamMode?play.players||[]:play.teams).map(t=>submissions[t.id]?.answer?`<div class="list-row help"><b>${esc(t.name)}</b><span>${esc(submissions[t.id].answer)}</span></div>`:'').join('')}`:''}</section>`;
}
function settingsPage(){return `<div class="toolbar"><div><div class="eyebrow">Set the atmosphere</div><h2>Make it sound like game night.</h2></div>${btn('Test celebration','test-sound','primary tiny')}</div><div class="settings"><div class="card"><div class="row"><label class="field">Visual theme<select data-setting="theme">${themes.map(t=>`<option ${game.theme===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Answer timer (seconds)<input data-setting="seconds" type="number" min="3" max="120" value="${settings().seconds}"></label><label class="field">Final timer (seconds)<input data-setting="finalSeconds" type="number" min="5" max="300" value="${settings().finalSeconds}"></label></div>${[['master','Master volume'],['effects','Sound effects'],['music','Original ambient music']].map(([k,t])=>`<label class="field">${t}<input class="range" data-setting="${k}" type="range" min="0" max="1" step=".05" value="${settings()[k]}"></label>`).join('')}<div class="row">${[['muted','Mute all audio'],['motion','Enable motion'],['autoplay','Autoplay clue media']].map(([k,t])=>`<label class="field">${t}<input type="checkbox" data-setting="${k}" ${settings()[k]?'checked':''}></label>`).join('')}</div></div><div class="card" style="margin-top:20px"><h3>Your soundboard</h3><p class="help">Original synthesized cues are included. Upload your own licensed audio to replace any cue.</p>${['select','buzz','correct','wrong','double','reveal','timer','win'].map(k=>`<div class="list-row"><strong>${k[0].toUpperCase()+k.slice(1)}</strong><span class="help">${esc(settings().sounds[k]?.name||'Original synth')}</span><div class="actions">${btn('▶','sound','tiny',`data-id="${k}"`)}${btn('Upload','upload-sound','tiny',`data-id="${k}"`)}${btn('Reset','reset-sound','tiny ghost',`data-id="${k}"`)}</div></div>`).join('')}</div><p class="help">Local play works after this page has been cached. Supabase phone rooms need internet. Browser audio starts after a tap. Local game files contain the answers: only share them with hosts.</p></div>`;}
function checkpoint(){editUndo.push(clone(game));if(editUndo.length>20)editUndo.shift();}
function details(){modal(`<h2>Game details</h2><form id="details-form">${field('Game title','name',game.name)}<label class="field">Theme<select name="theme">${themes.map(t=>`<option ${game.theme===t?'selected':''}>${t}</option>`).join('')}</select></label><button class="primary">Save game details</button></form>`);}
function editClue(cid,final=false){const q=final?game.final:game.rounds[editRound].flatMap(c=>c.clues).find(q=>q.id===cid);editing={q,final,media:q.media};modal(`<h2>${final?'Final showdown':'Write a great clue'}</h2><form id="clue-form">${final?field('Final category','finalCategory',game.finalCategory):''}${textField('Question / clue','question',q.question)}${textField('Correct answer','answer',q.answer)}${field('Also accept (equivalent answers)','accepted',q.accepted)}<div class="row">${field('Point value','value',q.value,'number')}${!final?`<label class="field">Daily Double (moves the round’s star here)<input name="dailyDouble" type="checkbox" ${q.dailyDouble?'checked':''}></label>`:''}</div>${field('Source URL','source',q.source,'url')}${textField('Private host notes','note',q.note)}<div class="drop" id="media-drop">Upload a picture and crop it, or add a short audio/video clip · ${window.GAME_NIGHT_CLOUD?'3':'25'} MB max<br><input type="file" id="clue-media" accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm,audio/mpeg,audio/wav,audio/ogg"></div><div class="row"><label class="field">Music link · direct audio or YouTube<input id="music-link" type="url" placeholder="https://…"></label>${btn('Add music link','add-music-link','tiny','type="button"')}</div><p class="help">YouTube plays visibly in your private host console. The public board shows a guessing prompt. Uploaded audio plays directly on the board.</p><div id="media-preview">${mediaHtml(q.media)}</div><div class="actions" style="margin:15px 0">${btn('Remove media','remove-media','tiny','type="button"')}<button class="primary" type="submit">Save clue</button></div></form>`);editing={q,final,media:q.media};}
async function fileData(file){if(!file)throw Error('Choose a file');if(file.size>25*1024*1024)throw Error('Keep each media file under 25 MB');const allowed=/^(image\/(png|jpeg|webp|gif)|video\/(mp4|webm)|audio\/(mpeg|wav|x-wav|ogg))$/;if(!allowed.test(file.type))throw Error('Use JPG, PNG, WEBP, GIF, MP4, WEBM, MP3, WAV or OGG');return {id:id(),name:file.name,type:file.type,data:await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file);})};}
function pickFile(accept,cb){const f=document.createElement('input');f.type='file';f.accept=accept;f.onchange=async()=>{try{await cb(f.files[0]);}catch(e){toast(e.message);}};f.click();}
function exportGame(){const blob=new Blob([JSON.stringify({format:'shane-family-game',version:1,game},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=game.name.replace(/[^a-z0-9]+/gi,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Game and media exported. Keep this backup.');}
function teamSetupCard(t,i){return `<article class="team-setup-card" data-team-id="${t.id}"><div class="team-number" style="background:${esc(t.color)}">${i+1}</div><label class="field">Team name<input data-setup-name="${t.id}" maxlength="28" value="${esc(t.name)}" required></label><label class="field team-color">Color<input type="color" data-setup-color="${t.id}" value="${esc(t.color)}"></label>${btn('×','remove-setup-team','ghost','type="button" data-id="'+t.id+'" aria-label="Delete team '+(i+1)+'"')}</article>`;}
function drawSetupTeams(){const list=$('#setup-team-list');if(list)list.innerHTML=setupTeams.map(teamSetupCard).join('');}
function setup(gid){if(gid)game=games.find(g=>g.id===gid);setupTeams=[{id:id(),name:'Team One',color:pickColors[0]},{id:id(),name:'The Challengers',color:pickColors[1]}];modal(`<h2>Build your lineup.</h2><p class="help">Add a card for each local team. Phone players join separately when you connect an online room.</p><form id="setup-form"><p><strong>${esc(game.name)}</strong></p><div id="setup-team-list" class="team-setup-list"></div>${btn('＋ Add team','add-setup-team','purple','type="button"')}<p class="help">Start with 2–32 local teams. Starting a new game replaces the current score session.</p><button class="primary">Start local game →</button></form>`);drawSetupTeams();}
function teamsModal(){if(room&&play.teamMode){onlineTeamsModal();return;}modal(`<h2>Your lineup.</h2>${room?btn('Enable team play','enable-team-play','primary'):''}<div class="team-setup-list">${play.teams.map(t=>`<article class="team-setup-card">${avatar(t)}<span style="flex:1">${esc(t.name)}<small> · ${t.score} points</small></span>${btn('Edit card','edit-team','tiny',`data-id="${t.id}"`)}${!room?btn('Delete','delete-team','tiny ghost',`data-id="${t.id}"`):''}</article>`).join('')}</div>${!room&&play.teams.length<32?btn('＋ Add team','add-team','primary','style="margin-top:20px"'):''}<p class="help">${room?'Online players join from their phones. Online team assignment is part of the upcoming session engine.':'Edit names, photos, and colors anytime. Deleting a team also removes its score history.'}</p>`);}
function onlineTeamsModal(){modal(`<h2>Teams & players</h2><p class="help">Players can choose a team on their phones. You can assign them here between questions.</p><div class="team-setup-list">${play.teams.map(t=>`<article class="team-setup-card"><span style="flex:1"><strong>${esc(t.name)}</strong><small> · ${t.score} points · ${(play.players||[]).filter(p=>p.teamId===t.id).length} players</small></span>${btn('Edit','edit-team','tiny',`data-id="${t.id}"`)}${btn('Delete','delete-team','tiny ghost',`data-id="${t.id}"`)}</article>`).join('')}</div>${btn('＋ Add team','add-team','primary')}<h3>Player assignments</h3>${(play.players||[]).map(p=>`<label class="field">${esc(p.name)}<select data-assign-player="${p.id}" ${play.phase!=='board'?'disabled':''}><option value="">Choose a team</option>${play.teams.map(t=>`<option value="${t.id}" ${p.teamId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label>`).join('')||'<p>No phone players have joined yet.</p>'}`);}
// Phone picking is two steps: tap a category, then choose how much. Used values stay as empty slots so nothing shifts.
const pickColors=['#ff2e88','#22e3ff','#b6ff3b','#ffd23f','#a77bff','#ff7a2e'];let pickCat=null;
function phonePicks(v){const cat=v.board[pickCat];if(!cat||cat.clues.every(q=>v.used.includes(q.id)))pickCat=null;if(pickCat==null)return `<div class="phone-picks"><h3><span>STEP 1</span>Pick a category</h3><div class="pick-cats">${v.board.map((c,i)=>{const done=c.clues.every(q=>v.used.includes(q.id));return btn(`${esc(c.name)}${done?'<small>DONE</small>':''}`,'pick-cat','pick-cat',`style="--col:${pickColors[i%6]}" data-index="${i}" ${done?'disabled':''}`);}).join('')}</div></div>`;return `<div class="phone-picks" style="--col:${pickColors[pickCat%6]}"><h3><span>STEP 2</span>How much?</h3><div class="pick-chosen">${esc(cat.name)}</div><div class="pick-values">${cat.clues.map(q=>v.used.includes(q.id)?'<span class="pick-used" aria-hidden="true"></span>':btn(String(q.value),'player-pick','pick-value',`data-id="${q.id}" aria-label="${esc(cat.name)} for ${q.value}"`)).join('')}</div>${btn('← Change category','pick-back','pick-back')}</div>`;}
function playerTurn(v,profile){const team=v.teams.find(t=>t.id===(v.teamMode?profile.teamId:profile.id));if(!team)return '';const pick=v.representatives?.[team.id],ans=v.answerers?.[team.id]||pick,choosing=v.phase==='board'&&v.active===team.id,picking=choosing&&pick?.id===profile.id,answering=v.phase!=='board'&&ans?.id===profile.id;return `<div class="player-turn ${picking?'your-turn role-pick':answering?'your-turn role-answer':''}"><span class="eyebrow">${esc(team.name)} · THIS TURN</span><h3>${picking?'You’re up!':answering?'You’re answering!':choosing?esc(pick?.name||'Your teammate')+' is picking':'Cheer your team on'}</h3><p>On turn: ${esc(pick?.name||'—')} · picks and answers</p></div>${picking&&v.started?phonePicks(v):''}`;}
const teamColor=(v,t)=>t?.color||['#ff3d8b','#22d3ee','#a3ff3d','#ffb020','#b46bff','#ff6a3d'][Math.max(0,v.teams.indexOf(t))%6];
function playerTeamPicker(v,p){return `<div class="card phone-teams"><h3>${p?.teamId?'Your team':'Pick your team'}</h3><p class="help">${v.phase==='board'?'Tap a team to join it.':'Team changes reopen after this question.'}</p><div class="phone-team-grid">${v.teams.map(t=>btn(`${esc(t.name)}${p?.teamId===t.id?' ✓':''}`,'join-team',p?.teamId===t.id?'phone-team-btn chosen':'phone-team-btn',`style="--c:${esc(teamColor(v,t))}" data-id="${t.id}" ${v.phase!=='board'?'disabled':''}`)).join('')}</div></div>`;}
function editTeam(tid){const t=play.teams.find(t=>t.id===tid);modal(`<h2>Player card</h2><form id="team-form" data-id="${tid}">${field('Name','name',t.name)}${field('Team color','color',t.color||'#a78bfa','color')}<div class="actions">${avatar(t)}${btn('Choose & crop photo','team-photo','tiny','type="button" data-id="'+tid+'"')}</div><button class="primary" style="margin-top:20px">Save card</button></form>`);}
async function crop(file,done,clue=false){const asset=await fileData(file);if(!asset.type.startsWith('image/'))throw Error('Choose an image');const img=new Image();img.src=asset.data;await img.decode();modal(`<h2>${clue?'Frame your picture clue.':'Frame your player.'}</h2><p class="help">Drag to move. Use the slider to zoom. Your ${clue?'clue':'card'} stays square.</p><canvas class="crop" id="crop" width="640" height="640"></canvas><label class="field" style="margin-top:18px">Zoom<input id="crop-zoom" type="range" min="1" max="4" step=".01" value="1"></label><div class="actions">${btn('Reset','crop-reset','ghost')}${btn('Crop & apply','crop-apply','primary')}</div>`);let zoom=1,x=0,y=0,start=null;const canvas=$('#crop'),ctx=canvas.getContext('2d'),base=Math.max(640/img.width,640/img.height);function draw(){const w=img.width*base*zoom,h=img.height*base*zoom;x=Math.max(-(w-640)/2,Math.min((w-640)/2,x));y=Math.max(-(h-640)/2,Math.min((h-640)/2,y));ctx.clearRect(0,0,640,640);ctx.drawImage(img,(640-w)/2+x,(640-h)/2+y,w,h);}draw();canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);start={x:e.clientX,y:e.clientY,ox:x,oy:y};};canvas.onpointermove=e=>{if(!start)return;const scale=640/canvas.getBoundingClientRect().width;x=start.ox+(e.clientX-start.x)*scale;y=start.oy+(e.clientY-start.y)*scale;draw();};canvas.onpointerup=canvas.onpointercancel=()=>start=null;$('#crop-zoom').oninput=e=>{zoom=+e.target.value;draw();};$('[data-action="crop-reset"]').onclick=()=>{zoom=1;x=y=0;$('#crop-zoom').value=1;draw();};$('[data-action="crop-apply"]').onclick=async()=>{const out=document.createElement('canvas');out.width=out.height=clue?960:320;out.getContext('2d').drawImage(canvas,0,0,out.width,out.height);await done(out.toDataURL('image/jpeg',.82));};}
async function connect(){if(room){roomLinks();return;}modal(`<h2>Connect player phones.</h2><p>Start a private online room and show a QR code for players to scan.</p><p class="help">Phone players join the teams you created. Your teams and scores carry over. Your saved game and questions stay available.</p><div class="actions">${btn('Create phone room','create-phone-room','primary')}${btn('Cancel','dismiss','ghost')}</div>`);}
async function createPhoneRoom(quiet=false){if(connecting)return false;connecting=true;modal(`<h2>Creating your room…</h2><p role="status" aria-live="polite">Connecting to the game service. Your room code will appear here. The QR is on the TV board.</p>`);const nextPlay=clone(play);nextPlay.teamMode=true;nextPlay.players=play.players||[];nextPlay.turns=play.turns||{};nextPlay.started=!!(play.used.length||play.selected);nextPlay.active=play.active||nextPlay.teams[0]?.id;const candidate={token:id()+id(),code:''};try{const state={game,play:nextPlay,settings:game.settings};const d=await api('create',candidate,{state,public:view(game,nextPlay)});if(!d.code)throw Error('The game service did not return a room code');play=nextPlay;room={...candidate,code:d.code,version:d.version};changed(false);await save();render();if(quiet){dismiss();toast('Room '+room.code+' is live. Players scan the QR on the TV.');}else roomLinks();return true;}catch(e){const message=e.name==='TimeoutError'?'The game service took too long to respond. Please retry.':e.message;modal(`<h2>Couldn’t connect phones.</h2><p role="alert">${esc(message)}</p><p class="help">Your local game and scores have been kept.</p><div class="actions">${btn('Retry connection','create-phone-room','primary')}${btn('Back to game','dismiss','ghost')}</div>`);return false;}finally{connecting=false;}}
// Sites cannot grant themselves pop-up permission. A plain link always opens, and the steps let the host allow pop-ups once.
function tvBlocked(href){modal(`<div class="eyebrow">ONE-TIME SETUP</div><h2>Open the TV board</h2><p>Your browser blocked the TV window. This button opens it right now:</p><a class="primary tv-link" href="${esc(href)}" target="family-game-stage" data-tv-link>📺 Open TV board</a><p class="help">To skip this step next time, allow pop-ups for this site once:</p><ul class="popup-help"><li><b>Chrome / Edge:</b> click the blocked pop-up icon at the right end of the address bar, choose <i>Always allow pop-ups and redirects</i> from this site, then Done.</li><li><b>Safari (Mac):</b> Safari menu → Settings → Websites → Pop-up Windows → set this site to <i>Allow</i>.</li><li><b>Firefox:</b> click <i>Options</i> in the yellow bar → <i>Allow pop-ups</i> for this site.</li></ul>`);}
function offerRecovery(code){modal(`<div class="eyebrow">YOUR GAME IS STILL LIVE</div><h2>Room ${esc(code)}</h2><p>Rejoin as Game Master to pick up right where you left off. Scores, players and the board stay exactly as they are.</p><div class="actions">${btn('↻ Rejoin as Game Master','reclaim-room','primary',`data-code="${esc(code)}"`)}${btn('Not now','dismiss','ghost')}</div><p class="help">Rejoining here takes control from any other Game Master window.</p>`);}
function roomLinks(){const url=new URL(location.href);url.search='?mode=player&room='+room.code;const tv=new URL(location.href);tv.search='?mode=stage&room='+room.code;modal(`<h2>Your room is ${room.code}</h2><p class="help">Players open the player link on their phones. Rooms expire after 24 hours. Players need only the room link and a name. Keep the Game Master window private.</p>${field('Player link','player-link',url.href)}${btn('Copy player link','copy-link','primary',`data-link="${esc(url.href)}"`)}<p class="help" style="margin-top:18px">TV link: <a href="${esc(tv.href)}" target="_blank">Open the shared board ↗</a></p><p class="help">Keep the host console on this browser. Its private host key never goes in the shared link.</p>${btn('End online session on this device','disconnect','danger tiny')}`);}

async function sync(){if(!room||saving||mode!=='host'||hostRetired)return;saving=true;let sentReset=false,sentClear=false;try{if(dirty){dirty=false;const payload={version:room.version,state:{game:clone(game),play:clone(play),settings:clone(game.settings)},public:view(game,play),resetBuzz,clearSubmissions};sentReset=resetBuzz;sentClear=clearSubmissions;resetBuzz=false;clearSubmissions=false;const d=await api('update',room,payload);room.version=d.version;if(!dirty)receiveHost(d);}else{const d=await api('read',room);if(!dirty)receiveHost(d);}const el=$('#connection');if(el)el.textContent='Connected to Supabase · '+room.code;}catch(e){resetBuzz=resetBuzz||sentReset;clearSubmissions=clearSubmissions||sentClear;if(e.message.includes('Game changed')){dirty=false;toast('Another host window changed the game. Reload to recover its latest state.');}else if(e.message.includes('Game Master access')||e.message.includes('another Game Master')){dirty=false;hostRetired=true;toast('This game is now being run from another Game Master window.');}else{dirty=true;const el=$('#connection');if(el)el.textContent='Reconnecting · '+e.message;}}finally{saving=false;if(dirty&&!polling){polling=true;setTimeout(()=>{polling=false;sync();},1200);}}}
function receiveHost(d){if(!play)return;let needsRender=false;if(d.version>room.version&&d.state){if(dirty){toast('Another host changed this room. Reload before continuing.');return;}game=d.state.game;play=d.state.play;const i=games.findIndex(g=>g.id===game.id);if(i>=0)games[i]=game;room.version=d.version;needsRender=true;}submissions=d.submissions||{};if(d.version>room.version){room.version=d.version;}if(JSON.stringify(play.players||[])!==JSON.stringify(d.players||[])){play.players=d.players||[];needsRender=true;}if(!play.teamMode){for(const p of d.players||[]){let t=play.teams.find(x=>x.id===p.id);if(!t){play.teams.push({...p,score:0});needsRender=true;dirty=true;}else if(t.name!==p.name||t.photo!==p.photo){t.name=p.name;t.photo=p.photo;needsRender=true;dirty=true;}}}if(!play.active&&play.teams.length)play.active=play.teams[0].id;if(d.public?.buzzStartsAt&&play.buzzOpen)play.buzzStartsAt=d.public.buzzStartsAt;if(d.buzz?.winner&&play.buzzOpen){const player=(d.players||[]).find(p=>p.id===d.buzz.winner),team=play.teamMode?player?.teamId:d.buzz.winner;if(team){play.winner=team;play.winnerPlayer=d.buzz.winner;play.deadline=d.buzz.deadline;play.buzzOpen=false;tone('buzz');needsRender=true;dirty=true;}}if(play.phase==='board'&&play.started){const chooser=representative(play,play.active);const request=chooser&&submissions[chooser.id]?.pick;if(request&&!play.used.includes(request)){select(game,play,request);resetBuzz=true;clearSubmissions=true;dirty=true;needsRender=true;tone('select');}}const sig=JSON.stringify(submissions);if(sig!==receiveHost.sig){receiveHost.sig=sig;needsRender=true;}if(needsRender){changed(false);if($('#modal').open&&$('#modal h2')?.textContent==='Teams & players'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))onlineTeamsModal();if(tab==='host'&&!$('#modal').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))render();}}
function publicFromResponse(d){const v=d.public;if(!v)return null;v.players=d.players||[];v.representatives=Object.fromEntries(v.teams.map(t=>[t.id,representative({...v,players:v.players},t.id)]));v.answerers=Object.fromEntries(v.teams.map(t=>[t.id,answerer({...v,players:v.players},t.id)]));if(!v.teamMode)v.teams=(d.players||[]).map(p=>({...p,score:v.teams?.find(t=>t.id===p.id)?.score||0}));if(d.buzz?.winner){v.winnerPlayer=d.buzz.winner;const p=v.players.find(p=>p.id===d.buzz.winner);v.winner=v.teamMode?p?.teamId:d.buzz.winner;v.deadline=d.buzz.deadline;v.buzzOpen=false;}return v;}
function publicLobby(v){const code=initialCode||room?.code||'';const players=v.players||[];return `<main class="public-lobby"><div class="lobby-title"><span class="eyebrow">ULTIMATE GAME NIGHT · EVERYONE’S INVITED</span><h1>Get your people.<br><span>Game night is on.</span></h1><p>Scan. Enter your name. Pick your team.</p></div><section class="lobby-join"><div id="public-room-qr" aria-label="Scan to join this game"></div><p>JOIN AT THIS ROOM CODE</p><strong class="room-code">${esc(code)}</strong><span>No account or download needed.</span></section><section class="lobby-players"><div class="section-head"><h2>${players.length} ${players.length===1?'player':'players'} in the room</h2><span class="eyebrow">WAITING FOR GAME MASTER</span></div><div class="lobby-team-grid">${v.teams.map(t=>`<article class="lobby-team" style="--team-color:${esc(t.color||'#a78bfa')}"><h3>${esc(t.name)}</h3><div class="lobby-member-grid">${(v.teamMode?players.filter(p=>p.teamId===t.id):players.filter(p=>p.id===t.id)).map(p=>`<div class="lobby-player">${avatar(p)}<strong>${esc(p.name)}</strong></div>`).join('')||'<p class="help">Ready for your players</p>'}</div></article>`).join('')}</div>${v.teamMode&&players.some(p=>!v.teams.some(t=>t.id===p.teamId))?`<h3>Choosing a team</h3><div class="lobby-member-grid">${players.filter(p=>!v.teams.some(t=>t.id===p.teamId)).map(p=>`<div class="lobby-player">${avatar(p)}<strong>${esc(p.name)}</strong></div>`).join('')}</div>`:''}${!players.length?'<p class="lobby-wait">Your players appear here as soon as they join.</p>':''}</section></main>`;}
function paintPublicQR(){const target=$('#public-room-qr');if(!target||!window.qrcode)return;const code=initialCode||room?.code;if(!code)return;const url=new URL(location.href);url.search='?mode=player&room='+code;const q=window.qrcode(0,'M');q.addData(url.href);q.make();target.innerHTML=q.createSvgTag({cellSize:5,margin:12});}
function hostRoster(){if(!room)return '';return `<section class="card host-roster"><div class="section-head"><h3>Players · ${(play.players||[]).length}</h3></div><div class="host-roster-grid">${(play.players||[]).map(p=>`<div class="host-roster-player">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(play.teamMode?play.teams.find(t=>t.id===p.teamId)?.name||'Choose a team':p.name)}</small></span></div>`).join('')||'<p class="help">Open the TV board to show the QR code. Players appear here as they join.</p>'}</div></section>`;}
// The TV remembers whether its players panel is hidden. With it hidden, the board runs full width and a bar names who picks.
let railHidden=(()=>{try{return localStorage.getItem('ugn-rail')==='hidden';}catch{return false;}})();
function pickBar(v){const code=initialCode||room?.code,team=v.teams.find(t=>t.id===v.active),answering=v.winner&&!v.judged?.includes(v.winner)?v.teams.find(t=>t.id===v.winner):null,shown=answering||team,person=answering?(v.players?.find(p=>p.id===v.winnerPlayer)?.name||v.answerers?.[answering.id]?.name):v.representatives?.[v.active]?.name;return `<div class="pick-bar ${v.phase==='board'?'is-picking':''}" style="--c:${esc(teamColor(v,shown))}"><span>${v.phase==='board'?'NOW PICKING':answering?'ANSWERING':'UP NEXT'}</span><strong data-fit="18">${esc(shown?.name||'Game Master')}${v.teamMode&&person?' · '+esc(person):''}</strong>${code?`<em>JOIN · ${esc(code)}</em>`:''}</div>`;}
// Team names shrink to fit their box (wrapping up to two lines) and stay centred.
function fitNames(){document.querySelectorAll('[data-fit]').forEach(el=>{el.style.fontSize='';let size=parseFloat(getComputedStyle(el).fontSize);const min=Number(el.dataset.fit)||12;while(size>min&&(el.scrollWidth>el.clientWidth+1||el.scrollHeight>el.clientHeight+1)){size-=1;el.style.fontSize=size+'px';}});}
addEventListener('resize',()=>fitNames());
function renderStagePage(){const v=remote||localPublic;if(v)document.body.className=v.theme.toLowerCase().replace('’','').replaceAll(' ','-');$('#app').innerHTML=`<div class="stage-only"><div class="toolbar"><div class="eyebrow">ULTIMATE GAME NIGHT · PUBLIC DISPLAY</div><div class="actions">${btn('Fullscreen','fullscreen','tiny')}${btn('Enable sound','enable-audio','tiny')}</div></div>${v&&initialCode&&!v.started?publicLobby(v):v?`<div class="broadcast-layout ${railHidden?'rail-hidden':''}"><div class="broadcast-main">${stage(v)}${railHidden?pickBar(v):''}${btn(railHidden?'‹':'›','toggle-rail','rail-toggle',`aria-label="${railHidden?'Show':'Hide'} the players panel" aria-expanded="${!railHidden}" title="${railHidden?'Show':'Hide'} players"`)}</div>${railHidden?'':broadcastRail(v)}</div>`:stage(v)}${!v?`<p class="center help">${initialCode?'Connecting to room '+esc(initialCode)+'…':'Start a game in your host tab. Keep both tabs on the same browser, or use an online room for another device.'}</p>`:''}</div>`;paintPublicQR();fitNames();}
function renderPlayer(){const d=playerData,v=d?publicFromResponse(d):null;if(v)document.body.className=v.theme.toLowerCase().replace('’','').replaceAll(' ','-');if(!d?.me){$('#app').innerHTML=`<div class="join-screen"><picture class="login-art"><source media="(max-width:700px)" srcset="${window.GAME_NIGHT_CLOUD?'/game-night-assets/':''}assets/menu-neon-mobile.jpg"><img src="${window.GAME_NIGHT_CLOUD?'/game-night-assets/':''}assets/menu-neon.jpg" alt=""></picture><main class="login-card"><div class="login-kicker">YOU’RE INVITED</div><h1>Let’s <span>play.</span></h1>${initialCode?`<div class="join-found">✓ Room <b>${esc(initialCode)}</b> found</div><ol class="how-steps"><li><b>1</b>Type your name</li><li><b>2</b>Pick your team. Your phone is your buzzer!</li></ol><form id="join-form"><input type="hidden" name="code" value="${esc(initialCode)}">`:`<div class="join-ways"><div class="join-way"><span>📷</span><div><b>Scan the QR on the TV</b><small>Point your phone’s camera at it and tap the link that pops up.</small></div></div><div class="join-or">or type the code</div></div><form id="join-form">${field('Room code','code',playerRoom?.code||'')}`}${field('Your name','name',playerRoom?.name||'')}<button class="login-go">ϟ Join the room</button></form><a class="login-back center" href="${window.GAME_NIGHT_CLOUD?'/game-night':'./'}">← Back to the studio</a></main></div>`;const code=$('#join-form [name=code]');if(code){code.maxLength=6;code.autocapitalize='characters';code.autocomplete='off';}return;}const profile=d.players.find(p=>p.id===d.me),me=v.teams.find(t=>t.id===(v.teamMode?profile?.teamId:d.me)),winner=v.winnerPlayer?v.winnerPlayer===d.me:!!me&&v.winner===me.id;const canBuzz=!!(v.buzzOpen&&!v.winner&&!v.judged?.includes(me?.id)&&(!v.teamMode||(me&&v.answerers?.[me.id]?.id===profile?.id))),picking=v.phase==='board'&&v.started&&me&&v.active===me.id&&v.representatives?.[me.id]?.id===profile?.id,state=winner?'in':canBuzz?'buzz':picking?'pick':'wait';$('#app').innerHTML=`<div class="join phone phone-${state} ${v.phase==='board'?'phone-board':''}" style="--team:${esc(teamColor(v,me))}"><header class="phone-hero"><div class="phone-hero-top"><span class="phone-room">ROOM ${esc(playerRoom.code)}</span>${btn('✎ Edit','player-profile','phone-edit')}</div><h2 class="phone-name" data-text="${esc(profile?.name||me?.name)}">${esc(profile?.name||me?.name)}</h2><div class="phone-meta"><span class="phone-team">${esc(me?.name||'No team yet')}</span><span class="phone-score"><b>${me?.score||0}</b> PTS</span></div></header>${v.teamMode&&(!profile?.teamId||v.phase==='board'&&!v.started)?playerTeamPicker(v,profile):''}${profile?playerTurn(v,profile):''}${v.phase==='standings'?stage(v):v.phase==='final-category'&&(!v.teamMode||v.answerers?.[me?.id]?.id===profile?.id)?`<div class="card"><div class="eyebrow">Final category</div><h2 style="margin:18px 0">${esc(v.finalCategory)}</h2><form id="wager-form">${field('Private wager · max '+Math.max(0,me?.score||0),'wager',0,'number')}<button class="primary">Submit wager</button></form></div>`:`${v.clue?`<div class="card phone-clue"><p>${esc(v.clue.question)}</p>${mediaHtml(v.clue.media)}${v.clue.answer?`<b style="color:var(--gold)">${esc(v.clue.answer)}</b>`:''}</div>`:''}<button class="buzzer${winner?' is-in':''}" data-action="buzz" data-eligible="${!!(v.buzzOpen&&!v.winner&&!v.judged?.includes(me?.id)&&(!v.teamMode||(me&&v.answerers?.[me.id]?.id===profile?.id)))}" data-opens-at="${v.buzzStartsAt||0}" ${v.buzzOpen&&serverNow()>=(v.buzzStartsAt||0)&&!v.winner&&!v.judged?.includes(me?.id)&&(!v.teamMode||(me&&v.answerers?.[me.id]?.id===profile?.id))?'':'disabled'}>${winner?'YOU’RE IN':canBuzz?(serverNow()>=(v.buzzStartsAt||0)?'BUZZ':Math.min(3,Math.max(1,Math.ceil(((v.buzzStartsAt||0)-serverNow())/1000)))):'LOCKED'}</button><p class="center muted phone-note">${winner?'You’re answering. Say it out loud!':v.winner?esc(v.teams.find(t=>t.id===v.winner)?.name)+' is answering':canBuzz?'Fastest buzz steals it. Hit BUZZ the moment it lights up!':v.roast?esc(v.roast):!v.started?'Waiting for the Game Master to start this room…':v.phase==='board'?'Waiting for the next clue…':'Wait for the host to open buzzers.'}</p><div class="center timer" data-deadline="${v.deadline||''}"></div>${(winner&&v.deadline>Date.now())||(v.phase==='final-clue'&&v.deadline>Date.now()&&(!v.teamMode||v.answerers?.[me?.id]?.id===profile?.id))?`<form id="answer-form">${textField('Your private answer','answer','')}<button class="primary">Send answer</button></form>`:''}`}</div>`;}
async function pollRemote(){if(mode==='host'){if(room&&!saving)sync();return;}if(!initialCode&&!playerRoom?.code)return;if(pollRemote.busy)return;pollRemote.busy=true;try{const r=playerRoom||{code:initialCode,token:sessionStorage.getItem('spectator-token')||id()+id()};if(!playerRoom)sessionStorage.setItem('spectator-token',r.token);const sentAt=Date.now(),d=await api('read',r,{knownRevision:pollRemote.revision??-1});if(Number.isFinite(d.serverTime))clockOffset=d.serverTime-((sentAt+Date.now())/2);if(d.unchanged){if(mode==='player'&&pollRemote.pendingUI&&!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)&&!$('#modal').open){pollRemote.pendingUI=false;renderPlayer();}return;}pollRemote.revision=d.revision;const signature=JSON.stringify(d);if(signature!==pollRemote.sig){if(mode==='stage'){pollRemote.sig=signature;const next=publicFromResponse(d);if(remote){if(next.phase==='standings'&&remote.phase!=='standings')tone('win');else if(next.revealed&&!remote.revealed)tone('reveal');else if(next.winner&&next.winner!==remote.winner)tone('buzz');else if(next.selected!==remote.selected&&next.selected)tone(next.phase==='double'?'double':'select');else if(JSON.stringify(next.teams.map(t=>t.score))!==JSON.stringify(remote.teams.map(t=>t.score)))tone(next.teams.some((t,i)=>t.score>(remote.teams[i]?.score||0))?'correct':'wrong');}remote=next;renderStagePage();}else{const changedPhase=playerData?.public?.phase!==d.public?.phase||playerData?.buzz?.winner!==d.buzz?.winner;playerData=d;if(changedPhase||(!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)&&!$('#modal').open)){pollRemote.sig=signature;pollRemote.pendingUI=false;renderPlayer();}else pollRemote.pendingUI=true;}}}catch(e){if(!pollRemote.error){toast(e.message);pollRemote.error=true;}}finally{pollRemote.busy=false;}}
async function action(a,b){const tid=b?.dataset?.team||play?.winner||play?.active;switch(a){
case 'home':case 'games':case 'builder':case 'settings':if(a==='builder'&&room){toast('Disconnect the room before editing this game.');return;}tab=a;render();break;
case 'dismiss':dismiss();break;
case 'join':location.href=location.pathname+'?mode=player';break;
case 'create':{if(room){toast('Disconnect the room before creating another game.');return;}const name=prompt('Name your game','Our Family Showdown');if(!name)return;game=makeGame(name.slice(0,120));games.push(game);editUndo=[];tab='builder';changed(false);render();break;}
case 'edit-game':if(room){toast('Disconnect the room before switching games.');return;}game=games.find(g=>g.id===b.dataset.id);tab='builder';editUndo=[];changed(false);render();break;
case 'details':details();break;
case 'game-menu':if(room){toast('Disconnect the room before managing games.');return;}game=games.find(g=>g.id===b.dataset.id);modal(`<h2>${esc(game.name)}</h2><div class="actions">${btn('Duplicate','duplicate','primary')}${btn('Export backup','export')}${btn('Delete game','delete-game','danger')}</div>`);break;
case 'duplicate':{const g=clone(game);g.id=id();g.name+=' — copy';games.push(g);game=g;dismiss();changed(false);render();break;}
case 'delete-game':if(games.length===1){toast('Keep at least one game in the studio.');return;}if(!confirm('Delete this game from this device? Export a backup first if you need it.'))return;games=games.filter(g=>g.id!==game.id);game=games[0];dismiss();changed(false);render();break;
case 'export':exportGame();break;
case 'import':if(room){toast('Disconnect the room before importing.');return;}pickFile('.json,application/json',async f=>{if(f.size>80*1024*1024)throw Error('Game file is too large (80 MB maximum)');const data=JSON.parse(await f.text());const g=validate(data.game||data);g.id=id();g.settings={...makeGame().settings,...g.settings};g.settings.sounds||={};games.push(g);game=g;changed(false);render();toast('Game imported, including its media.');});break;
case 'undo-edit':if(editUndo.length){const old=editUndo.pop();games[games.findIndex(g=>g.id===game.id)]=old;game=old;changed(false);render();}break;
case 'round-0':case 'round-1':editRound=+a.at(-1);render();break;
case 'edit-final':editClue(null,true);break;
case 'select-slot':selectedSlot=+b.dataset.index;render();break;
case 'add-category':{const cat=catalog.find(c=>c.id===b.dataset.id);if(!cat)return;const round=game.rounds[editRound>1?0:editRound];modal(`<h2>Add “${esc(cat.name)}”</h2><p class="help">Pick the slot it replaces. You can undo this with Undo edit.</p><div class="slot-pick">${round.map((c,i)=>btn(`<b>${i+1}</b>${esc(c.name)}`,'place-category','slot-pick-btn',`data-id="${cat.id}" data-index="${i}"`)).join('')}</div>`);break;}
case 'place-category':{const cat=catalog.find(c=>c.id===b.dataset.id);if(!cat)return;dismiss();replaceCategory(cat,Number(b.dataset.index));break;}
case 'new-category':{const name=prompt('Category name');if(!name)return;const c={id:id(),name:name.slice(0,80),clues:Array.from({length:5},(_,i)=>({id:id(),question:'',answer:'',accepted:'',value:(i+1)*100,hint:'',note:'',source:'',media:null,dailyDouble:false}))};catalog.unshift(c);replaceCategory(c,selectedSlot);break;}
case 'category-menu':{const i=+b.dataset.index;modal(`<h2>${esc(game.rounds[editRound][i].name)}</h2><div class="actions">${btn('Rename','rename-category','',`data-index="${i}"`)}${btn('Save to library','save-category','',`data-index="${i}"`)}${btn('Move left','move-category','',`data-index="${i}" data-dir="-1"`)}${btn('Move right','move-category','',`data-index="${i}" data-dir="1"`)}${btn('Clear slot','clear-category','danger',`data-index="${i}"`)}</div>`);break;}
case 'rename-category':{const c=game.rounds[editRound][+b.dataset.index],name=prompt('Category name',c.name);if(name){checkpoint();c.name=name.slice(0,80);changed(false);dismiss();render();}break;}
case 'save-category':catalog.unshift({...clone(game.rounds[editRound][+b.dataset.index]),id:id()});changed(false);dismiss();render();toast('Saved to your category library.');break;
case 'move-category':{const i=+b.dataset.index,j=i+(+b.dataset.dir);if(j<0||j>5)return;checkpoint();const r=game.rounds[editRound];[r[i],r[j]]=[r[j],r[i]];dismiss();changed(false);render();break;}
case 'clear-category':{if(!confirm('Clear this category and all five clues?'))return;checkpoint();const c=game.rounds[editRound][+b.dataset.index];c.name='New category';c.clues.forEach(q=>Object.assign(q,{question:'',answer:'',accepted:'',note:'',source:'',media:null,dailyDouble:false}));dismiss();changed(false);render();break;}
case 'edit-clue':editClue(b.dataset.id);break;
case 'add-music-link':if(editing){editing.media=linkedMedia($('#music-link').value.trim());$('#media-preview').innerHTML=mediaHtml(editing.media);}break;
case 'read-narration':{const text=game.rounds[play.round].find(cat=>cat.clues.some(q=>q.id===play.selected))?.hostNarration;if(text&&'speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(text));}else toast('Read the narration aloud from your host panel.');break;}
case 'ai-assistant':{const category=game.rounds[editRound>1?0:editRound][selectedSlot];await openAiAssistant({modal,category,categories:game.rounds.flat(),onApply:async draft=>{checkpoint();if(draft.clues?.length)draft.clues.forEach((q,i)=>Object.assign(category.clues[i],{question:q.question,answer:q.answer,accepted:q.accepted||'',note:q.note||''}));if(draft.category)category.name=draft.category;if(draft.narration)category.hostNarration=draft.narration;changed(false);await save();dismiss();render();toast('Reviewed draft added. Check facts and answers before hosting.');}});break;}
case 'manage-hosts':await manageHosts();break;
case 'toggle-host':await hostAccount({username:b.dataset.id,action:b.dataset.enabled==='true'?'disable':'enable'});break;
case 'reset-host-password':{const password=prompt('New password (at least 12 characters)');if(password)await hostAccount({username:b.dataset.id,password,action:'reset'});break;}
case 'logout':await save();await fetch('/api/game-night/session',{method:'DELETE'});location.href='/game-night/login';break;
case 'remove-media':if(editing){editing.media=null;$('#media-preview').innerHTML='';}break;
case 'host-guide':showHostGuide();break;
case 'guide-next':case 'guide-back':showHostGuide(Number(b.dataset.index));break;
case 'setup':if(play&&(room||play.used.length||play.selected)){modal(`<div class="eyebrow">A GAME IS ALREADY RUNNING</div><h2>Keep playing?</h2><p>${room?'Room '+esc(room.code)+' is live with your players and scores. ':''}Continue it, or start a brand-new game. A new game ends the current scores${room?' and room':''}.</p><div class="actions">${btn('↻ Continue current game','resume','primary')}${btn('Start a new game','setup-new','danger',b.dataset.id?`data-id="${esc(b.dataset.id)}"`:'')}</div>`);break;}setup(b.dataset.id);break;
case 'setup-new':dismiss();setup(b.dataset.id);break;
case 'set-answering':{const team=b.dataset.team;if(!play.teams.some(t=>t.id===team)||play.judged.includes(team))return;play.winner=team;play.winnerPlayer=answerer(play,team)?.id||null;play.buzzOpen=false;play.buzzStartsAt=null;resetBuzz=true;changed();render();break;}
case 'reclaim-room':{const candidate={token:id()+id(),code:b.dataset.code};const d=await api('reclaim',candidate);if(!d.state?.game||!d.state?.play)throw Error('That room could not be recovered');game=d.state.game;play=d.state.play;room={...candidate,version:d.version};submissions=d.submissions||{};const i=games.findIndex(g=>g.id===game.id);if(i>=0)games[i]=game;else games.push(game);dirty=false;hostRetired=false;recoverCode=null;dismiss();tab='host';render();await save();toast('Back in room '+room.code+'. Scores and players intact.');break;}
case 'resume':if(play){game=games.find(g=>g.id===play.gameId)||game;tab='host';render();}break;
case 'rejoin-room':{if(!room)throw Error('No saved room to rejoin');const d=await api('read',room);if(!d.state?.game||!d.state?.play)throw Error('Room is no longer available to this Game Master');game=d.state.game;play=d.state.play;room.version=d.version;submissions=d.submissions||{};const index=games.findIndex(g=>g.id===game.id);if(index>=0)games[index]=game;else games.push(game);tab='host';render();await save();toast('Rejoined room '+room.code+' with scores and players intact');break;}
case 'teams':dismiss();teamsModal();break;
case 'edit-team':editTeam(b.dataset.id);break;
case 'add-setup-team':if(setupTeams.length>=32)throw Error('The local lineup supports up to 32 teams');setupTeams.push({id:id(),name:'Team '+(setupTeams.length+1),color:pickColors[setupTeams.length%pickColors.length]});drawSetupTeams();break;
case 'remove-setup-team':setupTeams=setupTeams.filter(t=>t.id!==b.dataset.id);drawSetupTeams();break;
case 'add-team':{if(play.teams.length>=32)throw Error('The local lineup supports up to 32 teams');const t={id:id(),name:'Team '+(play.teams.length+1),score:0,photo:'',color:'#a78bfa'};play.teams.push(t);changed();render();editTeam(t.id);break;}
case 'delete-team':{if(room&&!play.teamMode)throw Error('Enable team play to manage teams');if(play.phase!=='board')throw Error('Delete teams between questions');if(room&&(play.players||[]).some(p=>p.teamId===b.dataset.id))throw Error('Move this team’s players to another team before deleting it');if(play.teams.length<=2)throw Error('Keep at least two teams in this game');const t=play.teams.find(t=>t.id===b.dataset.id);if(!t)return;if(!confirm('Delete '+t.name+' and its score history?'))return;play.teams=play.teams.filter(x=>x.id!==t.id);play.history=play.history.filter(e=>e.teamId!==t.id);play.judged=play.judged.filter(x=>x!==t.id);delete play.wagers[t.id];if(play.active===t.id)play.active=play.teams[0].id;if(play.winner===t.id){play.winner=null;play.deadline=null;play.buzzOpen=false;}changed();render();teamsModal();break;}
case 'team-photo':{const t=play.teams.find(t=>t.id===b.dataset.id);pickFile('image/*',f=>crop(f,photo=>{t.photo=photo;changed();dismiss();render();teamsModal();}));break;}
case 'pick':if(play.teams.length<2){toast('Add or join at least two players first.');return;}if(room&&!play.started)throw Error('Click Start game after players join their teams.');play.started=true;select(game,play,b.dataset.id);resetBuzz=true;clearSubmissions=true;submissions={};tone(play.phase==='double'?'double':'select');changed();render();break;
case 'lock-double':{const t=play.teams.find(t=>t.id===play.active),w=Number($('#dd-wager').value);if(!t)throw Error('Choose the team taking the Daily Double');if(!Number.isInteger(w)||w<0||w>Math.max(t.score,500*(play.round+1)))throw Error('Enter a wager within the displayed limit');play.wager=w;play.phase='clue';play.winner=t.id;play.deadline=Date.now()+settings().seconds*1000;changed();render();break;}
case 'open-buzz':if(play.resolved||play.revealed)throw Error('This clue is closed. Return to the board.');if(current(game,play)?.dailyDouble){toast('Daily Double belongs to the selected team.');return;}if(play.judged.length>=play.teams.length){toast('All teams have answered. Return to the board.');return;}play.winner=null;play.winnerPlayer=null;play.deadline=null;play.roast=null;play.buzzOpen=true;play.buzzStartsAt=room?Date.now()+3200:null;resetBuzz=true;changed();render();break;
case 'reveal':play.revealed=true;play.buzzOpen=false;if(play.phase.startsWith('final'))play.phase='final-answer';tone('reveal');changed();render();break;
case 'correct':case 'wrong':if(!['clue','final-answer','final-clue','final-locked'].includes(play.phase))return;score(game,play,tid,a==='correct');tone(a==='correct'?'correct':'wrong');resetBuzz=true;changed();render();break;
case 'close-clue':closeClue(play);resetBuzz=true;clearSubmissions=true;submissions={};changed();render();break;
case 'undo-score':undo(play);changed();render();break;
case 'adjust':{if(!play.teams.length)return;modal(`<h2>Score adjustment</h2><form id="adjust-form"><label class="field">Player<select name="team">${play.teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label>${field('Points to add (negative subtracts)','delta',0,'number')}${field('Reason','reason','Host correction')}<button class="primary">Apply adjustment</button></form>`);break;}
case 'next-round':if(play.round===1){toast('Round two is the last board. Start Final showdown when ready.');return;}if(!confirm('Advance to round two? Any remaining round-one clues will be skipped.'))return;play.round=1;closeClue(play);changed();render();break;
case 'final':if(play.teams.length<2)throw Error('Add at least two players');if(!confirm('Start Final showdown? Wagers are limited to each player’s nonnegative score.'))return;play.phase='final-category';play.resolved=false;play.selected=null;play.winner=null;play.deadline=null;play.buzzOpen=false;play.revealed=false;play.judged=[];play.wagers={};resetBuzz=true;clearSubmissions=true;submissions={};tone('double');changed();render();break;
case 'lock-final':{for(const input of document.querySelectorAll('[data-wager]')){const t=play.teams.find(t=>t.id===input.dataset.wager),w=+input.value;if(!Number.isInteger(w)||w<0||w>Math.max(0,t.score))throw Error('Check the wager for '+t.name);play.wagers[t.id]=w;}play.phase='final-clue';play.deadline=Date.now()+settings().finalSeconds*1000;play.active=play.teams[0]?.id;changed();render();break;}
case 'standings':if(play.judged.length<play.teams.length&&!confirm('Some players have not been scored. Show standings anyway?'))return;play.phase='standings';play.deadline=null;tone('win');changed();render();break;
case 'start-online-game':if(play.teamMode&&!(play.players||[]).some(p=>play.teams.some(t=>t.id===p.teamId)))throw Error('Assign a joined player to a team first');play.started=true;changed();render();break;
case 'show-lobby':if(play.phase!=='board')throw Error('Return to the board before showing the joining lobby');play.started=false;changed();render();break;
case 'enable-team-play':if(play.phase!=='board')throw Error('Enable teams between questions');modal(`<h2>Enable team play?</h2><p>Your joined players stay in the room. Existing individual scores stay on their original cards. Add team cards, then assign players below.</p>${btn('Enable teams','confirm-team-play','primary')}`);break;
case 'confirm-team-play':play.teamMode=true;play.players=play.players||[];changed();await sync();render();teamsModal();break;
case 'pick-cat':pickCat=Number(b.dataset.index);renderPlayer();break;
case 'pick-back':pickCat=null;renderPlayer();break;
case 'player-pick':pickCat=null;playerData=await api('pick_request',playerRoom,{clueId:b.dataset.id});toast('Selection sent to the Game Master');renderPlayer();break;
case 'join-team':playerData=await api('assign_team',playerRoom,{teamId:b.dataset.id});renderPlayer();toast('Team selected');break;
case 'connect':await connect();break;
case 'create-phone-room':await createPhoneRoom();break;
case 'disconnect':if(!confirm('Disconnect this host from the online room? Players will no longer receive updates.'))return;room=null;dirty=false;dismiss();changed(false);render();break;
case 'tv':{dismiss();const tv=window.open('about:blank','family-game-stage');if(!room&&!(await createPhoneRoom(true))){tv?.close();break;}const url=new URL(location.href);url.search='?mode=stage&room='+room.code;if(!tv){tvBlocked(url.href);break;}tv.location.href=url.href;toast('Drag the TV window to your TV, then press Fullscreen.');changed(false);break;}
case 'tour-start':startTour();break;
case 'tour-next':tourStep=tourStep+1>=tourList().length?-1:tourStep+1;drawTour();break;
case 'tour-back':tourStep=Math.max(0,tourStep-1);drawTour();break;
case 'tour-end':tourStep=-1;drawTour();break;
case 'slots-prev':case 'slots-next':{const row=$('#slots'),card=row?.querySelector('.slot');if(card)row.scrollBy({left:(a==='slots-next'?1:-1)*(card.offsetWidth+12),behavior:'smooth'});break;}
case 'slots-go':{const card=$('#slots')?.children[Number(b.dataset.index)];card?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'start'});break;}
case 'toggle-rail':railHidden=!railHidden;try{localStorage.setItem('ugn-rail',railHidden?'hidden':'shown');}catch{}renderStagePage();break;
case 'fullscreen':await document.documentElement.requestFullscreen?.();break;
case 'enable-audio':showSound=true;tone('select');break;
case 'display-help':modal(`<h2>Take it to the big screen.</h2><p><strong>Computer:</strong> connect HDMI or use your computer’s display settings. Open TV board, move that window to the TV, then choose Fullscreen.</p><p><strong>Android:</strong> open the TV link on the receiving display’s browser, or use your phone’s screen-cast feature if supported.</p><p><strong>iPhone / iPad:</strong> use Screen Mirroring with an AirPlay-compatible display, or open the TV link directly on another device.</p><p class="help">Only mirror the public TV board. Your host console contains answers. A separate device requires an online room and access to this Site.</p>`);break;
case 'copy-link':await navigator.clipboard.writeText(b.dataset.link);toast('Player link copied');break;
case 'test-sound':tone('win');break;
case 'sound':tone(b.dataset.id);break;
case 'upload-sound':pickFile('audio/*',async f=>{const m=await fileData(f);if(!m.type.startsWith('audio/'))throw Error('Choose audio');settings().sounds[b.dataset.id]=m;changed();render();});break;
case 'reset-sound':delete settings().sounds[b.dataset.id];changed();render();break;
case 'buzz':{if(buzzPending)return;buzzPending=true;b.disabled=true;try{const opensAt=Number(b.dataset.opensAt||0),reaction=buzzShown.at===opensAt&&buzzShown.shown?Date.now()-buzzShown.shown:null;const d=await api('buzz',playerRoom,{reaction});playerData=d;tone('buzz');renderPlayer();}finally{buzzPending=false;}break;}
case 'player-profile':{const p=playerData.players.find(t=>t.id===playerData.me);modal(`<h2>Your player card</h2><form id="player-profile-form">${field('Name','name',p.name)}<button class="primary" style="margin-top:20px">Save card</button></form>`);break;}
case 'player-photo':{const p=playerData.players.find(t=>t.id===playerData.me);pickFile('image/*',f=>crop(f,async photo=>{playerData=await api('profile',playerRoom,{name:p.name,photo});dismiss();renderPlayer();}));break;}
}}
function replaceCategory(cat,index){const r=editRound>1?0:editRound;checkpoint();const c=clone(cat);c.id=id();c.clues.forEach((q,i)=>{q.id=id();q.value=(i+1)*100*(r+1);q.dailyDouble=false;});const hadDD=game.rounds[r][index].clues.some(q=>q.dailyDouble);if(hadDD)c.clues[3].dailyDouble=true;game.rounds[r][index]=c;changed(false);render();toast(`Added ${c.name} to slot ${index+1}`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){try{await action(b.dataset.action,b);}catch(err){toast(err.message);}}const mic=e.target.closest('[data-dictate]');if(mic){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('Use the microphone on your device keyboard to dictate here.');return;}const input=document.querySelector(`[name="${mic.dataset.dictate}"]`),r=new Speech();r.lang='en-US';r.interimResults=false;mic.textContent='Listening…';r.onresult=e=>{input.value+=(input.value?' ':'')+e.results[0][0].transcript;toast('Dictation added. Review it before saving.');};r.onend=()=>mic.textContent='◉ Dictate';r.onerror=()=>toast('Microphone unavailable. Check permission or use your keyboard mic.');r.start();}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=new FormData(f);try{switch(f.id){
case 'details-form':if(!String(d.get('name')).trim())throw Error('Enter a title');checkpoint();game.name=String(d.get('name')).trim().slice(0,120);game.theme=d.get('theme');dismiss();changed(false);render();break;
case 'host-account-form':await hostAccount(Object.fromEntries(d));break;
case 'clue-form':{const {q,final,media}=editing;if(!d.get('question').trim()||!d.get('answer').trim())throw Error('Add both a question and an answer');const value=+d.get('value');if(!Number.isInteger(value)||value<0)throw Error('Use a nonnegative whole point value');checkpoint();if(d.get('dailyDouble'))game.rounds[editRound].forEach(c=>c.clues.forEach(x=>x.dailyDouble=false));Object.assign(q,{question:d.get('question').trim(),answer:d.get('answer').trim(),accepted:d.get('accepted'),value,source:d.get('source'),note:d.get('note'),dailyDouble:!!d.get('dailyDouble'),media});if(final)game.finalCategory=d.get('finalCategory');dismiss();changed(false);render();break;}
case 'setup-form':{const names=setupTeams.map(t=>t.name.trim().slice(0,28));if(names.length<2||names.length>32||names.some(n=>!n))throw Error('Add 2–32 teams, each with a name');play=newPlay(game,names);play.teams.forEach((t,i)=>t.color=setupTeams[i].color);play.active=play.teams[0].id;room=null;tab='host';dismiss();tone('select');changed(false);render();showHostGuide();break;}
case 'team-form':{const t=play.teams.find(t=>t.id===f.dataset.id),name=d.get('name').trim().slice(0,28);if(!name)throw Error('Enter a name');t.name=name;t.color=d.get('color')||t.color;dismiss();changed();render();break;}
case 'adjust-form':{const delta=+d.get('delta');if(!Number.isSafeInteger(delta)||Math.abs(delta)>1000000)throw Error('Use whole points between -1000000 and 1000000');const t=play.teams.find(t=>t.id===d.get('team'));t.score+=delta;play.history.push({id:id(),teamId:t.id,delta,reason:d.get('reason'),selected:'manual',phase:'manual'});dismiss();changed();render();break;}
case 'join-form':{const code=d.get('code').trim().toUpperCase(),name=d.get('name').trim().slice(0,28);if(!/^[A-Z2-9]{6}$/.test(code)||!name)throw Error('Enter the room code and your name');const prior=await read('player-'+code);playerRoom=prior||{code,token:id()+id(),name};playerData=await api('join',playerRoom,{name});await write('player-'+code,playerRoom);history.replaceState(null,'',location.pathname+'?mode=player&room='+code);renderPlayer();break;}
case 'wager-form':{const w=+d.get('wager'),profile=playerData.players.find(p=>p.id===playerData.me),me=playerData.public.teams.find(t=>t.id===(playerData.public.teamMode?profile?.teamId:playerData.me));if(!Number.isInteger(w)||w<0||w>Math.max(0,me?.score||0))throw Error('Wager must fit your available points');playerData=await api('wager',playerRoom,{text:String(w)});toast('Private wager submitted. You can change it until the host locks.');break;}
case 'answer-form':await api('answer',playerRoom,{text:d.get('answer').trim()});toast('Your answer was sent privately to the host.');break;
case 'player-profile-form':{const me=playerData.players.find(t=>t.id===playerData.me),name=d.get('name').trim().slice(0,28);if(!name)throw Error('Enter a name');playerData=await api('profile',playerRoom,{name,photo:me.photo});dismiss();renderPlayer();break;}
}}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#library-list').innerHTML=libraryList();}});
document.addEventListener('input',e=>{const key=e.target.dataset.setupName||e.target.dataset.setupColor;if(!key)return;const t=setupTeams.find(t=>t.id===key);if(!t)return;if(e.target.dataset.setupName)t.name=e.target.value;else{t.color=e.target.value;e.target.closest('.team-setup-card').querySelector('.team-number').style.background=t.color;}});
document.addEventListener('change',async e=>{try{if(e.target.id==='clue-media'){await clueMedia(e.target.files[0]);}if(e.target.dataset.assignPlayer){if(!e.target.value)return;const response=await api('assign_team',room,{playerId:e.target.dataset.assignPlayer,teamId:e.target.value});receiveHost(response);changed(false);teamsModal();}if(e.target.dataset.wager){play.wagers[e.target.dataset.wager]=+e.target.value;changed(false);}if(e.target.id==='active-team'){play.active=e.target.value;play.winner=null;play.winnerPlayer=null;if(play.phase==='clue'&&play.active){play.winner=play.active;play.deadline=Date.now()+settings().seconds*1000;play.buzzOpen=false;}resetBuzz=true;changed();render();}if(e.target.dataset.setting){const k=e.target.dataset.setting;if(k==='theme')game.theme=e.target.value;else{let v=e.target.type==='checkbox'?e.target.checked:+e.target.value;if(k==='seconds')v=Math.min(120,Math.max(3,v||15));if(k==='finalSeconds')v=Math.min(300,Math.max(5,v||30));game.settings[k]=v;}setMusic();changed();render();}}catch(err){toast(err.message);}});
document.addEventListener('keydown',e=>{const t=e.target.closest?.('.lib-item');if(t&&(e.key==='Enter'||e.key===' ')){e.preventDefault();t.click();}});
document.addEventListener('dragstart',e=>{const b=e.target.closest('[data-drag]');if(b)e.dataTransfer.setData('text/plain',b.dataset.drag);});
document.addEventListener('dragover',e=>{const t=e.target.closest('[data-slot],#media-drop');if(t){e.preventDefault();document.querySelectorAll('.drop-target').forEach(x=>x!==t&&x.classList.remove('drop-target'));t.classList.add('drop-target');}});
document.addEventListener('dragleave',e=>{const t=e.target.closest('[data-slot]');if(t&&!t.contains(e.relatedTarget))t.classList.remove('drop-target');});
document.addEventListener('dragend',()=>document.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target')));
document.addEventListener('drop',async e=>{try{const drop=e.target.closest('#media-drop'),slot=e.target.closest('[data-slot]');if(drop){e.preventDefault();await clueMedia(e.dataTransfer.files[0]);}else if(slot){e.preventDefault();slot.classList.remove('drop-target');const c=catalog.find(x=>x.id===e.dataTransfer.getData('text/plain'));if(c)replaceCategory(c,+slot.dataset.slot);}}catch(err){toast(err.message);}});
channel.onmessage=e=>{if(e.data.type==='request'&&mode==='host'&&play)channel.postMessage({type:'stage',view:view(game,play)});if(mode==='stage'&&!initialCode&&e.data.type==='stage'){localPublic=e.data.view;renderStagePage();}};
window.addEventListener('keydown',e=>{if($('#modal').open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(mode==='player'&&e.code==='Space'){e.preventDefault();$('.buzzer:not(:disabled)')?.click();}if(tab==='host'&&e.key.toLowerCase()==='r'&&play?.phase==='clue'){action('reveal',{}).catch(e=>toast(e.message));}});
setInterval(()=>{document.querySelectorAll('.buzzer[data-eligible]').forEach(el=>{const eligible=el.dataset.eligible==='true',opensAt=Number(el.dataset.opensAt||0),armed=serverNow()>=opensAt;if(eligible&&armed&&buzzShown.at!==opensAt)buzzShown={at:opensAt,shown:Date.now()};el.disabled=!(eligible&&armed&&!buzzPending);if(eligible)el.textContent=armed?'BUZZ':String(Math.min(3,Math.max(1,Math.ceil((opensAt-serverNow())/1000))));});},30);
setInterval(()=>{document.querySelectorAll('[data-countdown]').forEach(el=>{const left=Number(el.dataset.countdown||0)-serverNow();el.textContent=left>0?String(Math.min(3,Math.ceil(left/1000))):'BUZZ!';el.classList.toggle('go',left<=0);});document.querySelectorAll('[data-deadline]').forEach(el=>{const end=+el.dataset.deadline;el.textContent=end?Math.max(0,Math.ceil((end-serverNow())/1000))+'s':'';});if(mode==='host'&&play?.deadline&&Date.now()>=play.deadline){play.deadline=null;play.buzzOpen=false;if(play.phase==='final-clue')play.phase='final-locked';tone('timer');changed();render();}},250);
setInterval(()=>{const active=mode==='host'?room&&play?.phase==='clue':mode==='player'?playerData?.public?.phase==='clue':remote?.phase==='clue';const interval=active?350:1150;if(Date.now()-lastPollAt>=interval){lastPollAt=Date.now();pollRemote();}},125);
async function init(){try{await openStore();if(mode==='host'){const saved=await read('studio');if(saved?.games?.length){games=saved.games;game=games.find(g=>g.id===saved.selected)||games[0];play=saved.play;room=saved.room;catalog=saved.catalog||catalog;games.forEach(g=>{if(g.name==='Shane’s Family Showdown')g.name='Ultimate Showdown';});}else{game=makeGame();games=[game];await save();}if(params.get('handoff')){const h=await read('host-handoff-'+params.get('handoff'));if(h&&h.username===window.GAME_USER?.username&&Date.now()-h.created<60000){games=h.games;game=games.find(g=>g.id===h.selected)||games[0];play=h.play;room=h.room;catalog=h.catalog;}const clean=new URL(location.href);clean.searchParams.delete('handoff');history.replaceState({},'',clean.href);}if(room){try{const d=await api('read',room);if(d.state?.game&&d.state?.play){game=d.state.game;play=d.state.play;const i=games.findIndex(g=>g.id===game.id);if(i>=0)games[i]=game;else games.push(game);room.version=d.version;if(!dirty)receiveHost(d);}else recoverCode='lost';}catch(e){recoverCode='lost';}}if(window.GAME_NIGHT_CLOUD&&(!room||recoverCode)){try{const m=await api('mine',{token:id()+id()});recoverCode=m.code||null;}catch{recoverCode=null;}}}else if(mode==='stage'){if(!initialCode)localPublic=await read('public-stage');channel.postMessage({type:'request'});}else if(initialCode){playerRoom=await read('player-'+initialCode);if(playerRoom)try{playerData=await api('read',playerRoom);}catch(e){toast(e.message);}}if(mode==='host'&&params.get('console')==='1'&&play)tab='host';render();if(recoverCode)offerRecovery(recoverCode);else if(mode==='host'&&tab==='home'){let seen=false;try{seen=!!localStorage.getItem('ugn-tour-seen');}catch{}if(!seen)setTimeout(startTour,600);}pollRemote();if(!window.GAME_NIGHT_CLOUD&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(e){$('#app').innerHTML=`<div class="join"><h2>We couldn’t open saved games.</h2><p>${esc(e.message)}</p><p>Allow browser storage and reload. Your exported backups can be imported once storage is available.</p><button onclick="location.reload()">Reload</button></div>`;}}
init();

function broadcastRail(v){const code=initialCode||room?.code;return `<aside class="broadcast-side">${code?`<section class="broadcast-join"><div id="public-room-qr"></div><div><span>SCAN TO JOIN</span><strong>${esc(code)}</strong></div></section>`:''}<section class="broadcast-roster"><h2>THE PLAYERS</h2>${v.teams.map(t=>`<article class="broadcast-team" style="--team-color:${esc(t.color||'#ffcb46')}"><h3>${esc(t.name)}</h3>${(v.players||[]).filter(p=>v.teamMode?p.teamId===t.id:p.id===t.id).map(p=>`<div class="broadcast-member ${v.representatives?.[t.id]?.id===p.id||v.answerers?.[t.id]?.id===p.id?'on-turn':''}">${avatar(p)}<strong>${esc(p.name)}</strong>${v.representatives?.[t.id]?.id===p.id?'<span>PICKS</span>':''}${v.answerers?.[t.id]?.id===p.id&&v.representatives?.[t.id]?.id!==p.id?'<span>ANSWERS</span>':''}</div>`).join('')}</article>`).join('')}</section></aside>`;}
